{
  "name": "sheaf-vscode-extension",
  "displayName": "Sheaf",
  "description": "Voice-driven realtime agent for VS Code (Sheaf)",
  "version": "0.0.1",
  "publisher": "sheaf",
  "private": true,
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Other"
  ],
  "activationEvents": [
    "onCommand:sheaf.realtime.toggleSession",
    "onCommand:sheaf.realtime.commitAndRespond",
    "onView:sheaf.chatView"
  ],
  "main": "./out/extension.js",
  "contributes": {
    "viewsContainers": {
      "activitybar": [
        {
          "id": "sheafContainer",
          "title": "Sheaf",
          "icon": "media/sheaf.svg"
        }
      ]
    },
    "views": {
      "sheafContainer": [
        {
          "id": "sheaf.chatView",
          "name": "Realtime Chat",
          "type": "webview"
        }
      ]
    },
    "commands": [
      {
        "command": "sheaf.realtime.toggleSession",
        "title": "Sheaf: Toggle Realtime Session"
      },
      {
        "command": "sheaf.realtime.commitAndRespond",
        "title": "Sheaf: Commit Audio And Request Response"
      }
    ],
    "keybindings": [
      {
        "command": "sheaf.realtime.toggleSession",
        "key": "f16"
      },
      {
        "command": "sheaf.realtime.commitAndRespond",
        "key": "f20"
      }
    ],
    "configuration": {
      "title": "Sheaf Realtime",
      "properties": {
        "sheaf.realtime.openAiApiKey": {
          "type": "string",
          "default": "",
          "description": "OpenAI API key (optional if stored in Secret Storage or OPENAI_API_KEY)."
        },
        "sheaf.realtime.model": {
          "type": "string",
          "default": "gpt-realtime-2"
        },
        "sheaf.realtime.systemPrompt": {
          "type": "string",
          "default": "",
          "description": "Overrides the built-in sheaf VS Code system prompt when non-empty."
        },
        "sheaf.realtime.inputDevice": {
          "type": "string",
          "default": "",
          "description": "Optional microphone device id or substring (see realtime-agent list-input-devices)."
        },
        "sheaf.realtime.safetyIdentifier": {
          "type": "string",
          "default": "",
          "description": "Optional safety identifier header for OpenAI Realtime."
        }
      }
    }
  },
  "scripts": {
    "build": "node esbuild.config.mjs",
    "dev": "node esbuild.config.mjs --watch",
    "lint": "tsc -p tsconfig.json --noEmit",
    "test": "rm -rf .test-dist && tsc -p tsconfig.test.json && node --test $(find .test-dist/test -name '*.test.js')",
    "prebuild": "npm run build --prefix ../realtime-agent"
  },
  "dependencies": {
    "better-sqlite3": "^12.10.0",
    "naudiodon": "^2.3.6"
  },
  "devDependencies": {
    "@types/node": "^22.10.1",
    "@types/vscode": "^1.85.0",
    "esbuild": "^0.24.0",
    "realtime-agent-lib": "file:../realtime-agent",
    "typescript": "^5.7.2"
  }
}

import { copyFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { build, context } from "esbuild";

const watch = process.argv.includes("--watch");

const rootDir = dirname(fileURLToPath(import.meta.url));

const extensionOptions = {
  entryPoints: ["src/extension.ts"],
  bundle: true,
  format: "cjs",
  platform: "node",
  target: "es2022",
  sourcemap: watch ? "inline" : false,
  outfile: "out/extension.js",
  external: ["vscode", "better-sqlite3", "naudiodon"],
  logLevel: "info",
};

const webviewOptions = {
  entryPoints: ["src/chat/webview/index.ts"],
  bundle: true,
  format: "iife",
  platform: "browser",
  target: "es2022",
  sourcemap: watch ? "inline" : false,
  outfile: "out/webview/index.js",
  logLevel: "info",
};

function CopyWebviewStyles()
{
  mkdirSync(join(rootDir, "out", "webview"), { recursive: true });
  copyFileSync(join(rootDir, "src", "chat", "webview", "index.css"), join(rootDir, "out", "webview", "index.css"));
}

if (watch)
{
  const ctxExt = await context(extensionOptions);
  const ctxWeb = await context(webviewOptions);
  CopyWebviewStyles();
  await Promise.all([ctxExt.watch(), ctxWeb.watch()]);
}
else
{
  await Promise.all([build(extensionOptions), build(webviewOptions)]);
  CopyWebviewStyles();
}

